import{_ as a,C as i,o as l,c as d,j as t,a as r,E as s,a2 as n}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Delivery","description":"","frontmatter":{"title":"Delivery"},"headers":[],"relativePath":"en/guide/release.md","filePath":"en/guide/release.md"}'),h={name:"en/guide/release.md"};function c(g,e,u,p,y,f){const o=i("Capture");return l(),d("div",null,[e[0]||(e[0]=t("h1",{id:"delivery",tabindex:"-1"},[r("Delivery "),t("a",{class:"header-anchor",href:"#delivery","aria-label":'Permalink to "Delivery"'},"​")],-1)),e[1]||(e[1]=t("p",null,[r("This screen, titled "),t("strong",null,"Delivery planning"),r(", delivers a new version: that of a module (recommended), or that of the whole project. You choose what to deliver, the plan is computed right away, then you run it after a summary.")],-1)),s(o,{name:"release",alt:"The Delivery screen: target choice, delivery plan and delivery configuration"}),e[2]||(e[2]=n('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>What to deliver?</strong> First, under <strong>Modules — recommended</strong>, the project&#39;s modules with their version. Below, <strong>Whole project</strong>. The first module is selected by default.</li><li><strong>Increment type</strong>: <strong>Patch</strong>, <strong>Minor</strong> or <strong>Major</strong>.</li><li>The plan of the chosen target: <ul><li>the current and target versions, for instance <code>1.4.0 → 1.4.1</code>;</li><li>the <strong>Tag</strong> that will be set, the <strong>Last tag</strong>, the <strong>Repository</strong> (the module&#39;s own, or the project&#39;s), the <strong>Release repository</strong>, the <strong>Branch</strong> and the <strong>Version files</strong>;</li><li><strong>Good to know</strong>: what to know before running, for instance a target version behind the last tag;</li><li>the <strong>Plan steps</strong>, each with its checkbox.</li></ul></li><li><strong>Delivery configuration</strong> (further down): each module&#39;s build command and artifacts.</li></ul><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="choose-what-to-deliver" tabindex="-1">Choose what to deliver <a class="header-anchor" href="#choose-what-to-deliver" aria-label="Permalink to &quot;Choose what to deliver&quot;">​</a></h3><p>Click a module, or <strong>Whole project</strong>. The plan is recomputed at once, without writing anything.</p><p>What changes with the target:</p><table tabindex="0"><thead><tr><th>Target</th><th>Version read from</th><th>Tag set</th><th>Git acts in</th></tr></thead><tbody><tr><td>Module with its own repository</td><td>its files (<code>package.json</code>, <code>Cargo.toml</code>…)</td><td><code>v1.4.1</code></td><td>its repository</td></tr><tr><td>Module in the project repository</td><td>its files</td><td><code>site-v1.4.1</code></td><td>the project repository, bounded to the module&#39;s path</td></tr><tr><td>Whole project</td><td><code>effortless.json</code> and the declared version files</td><td><code>v0.2.0</code></td><td>the project repository</td></tr></tbody></table><p>A module&#39;s version files are detected. To impose others, declare them in <code>stacks[].release.version_files</code> of <code>effortless.json</code>.</p><h3 id="choose-the-steps" tabindex="-1">Choose the steps <a class="header-anchor" href="#choose-the-steps" aria-label="Permalink to &quot;Choose the steps&quot;">​</a></h3><p>Check the steps to run: <strong>Bump the version</strong>, <strong>Commit and push</strong>, <strong>Tag and GitHub release</strong>, <strong>Update the documentation</strong>, <strong>Build and upload the artifacts</strong>. A step that does not apply to the target is greyed out. Your choices are remembered for this project; with nothing checked, the screen asks &quot;Check at least one step.&quot;</p><h3 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h3><ol><li>Click <strong>Run…</strong>. A panel sums up the target, version, tag, repository and steps.</li><li>Read it: these actions are real (version files written, commit, push, tag, GitHub release, build) and cannot be undone with a click.</li><li>Click <strong>Confirm and run</strong>.</li></ol>',12)),s(o,{name:"release-recap",alt:"The summary before running: target, version, tag, repository, branch and steps"}),e[3]||(e[3]=n('<p>The result shows step by step: <strong>done</strong>, <strong>to do by hand</strong> (the engine could not act and says why, for instance without <code>gh</code>), <strong>failed</strong>, or <strong>not run</strong> (an earlier step failed: the chain stops).</p><p>In semi-auto work mode, the run is refused and the panel says so.</p><p>A tag is never set on uncommitted files: without <strong>Commit and push</strong>, the new version would not be in the tagged commit. The step then fails and says so.</p><h3 id="deliver-internally-or-publicly" tabindex="-1">Deliver internally or publicly <a class="header-anchor" href="#deliver-internally-or-publicly" aria-label="Permalink to &quot;Deliver internally or publicly&quot;">​</a></h3><p>Under the target, choose the <strong>Channel</strong>:</p><ul><li><strong>Internal</strong>: the delivery described above. The release and its artifacts go to the internal <strong>Release repository</strong> (by default, the code&#39;s origin repository).</li><li><strong>Public</strong>: you publish a version <strong>already delivered internally</strong>, as is — same tag, same artifacts, no new bump. The screen only offers versions delivered internally and not yet public. If no public repository is declared for the target, it says so and points to the configuration further down.</li></ul><p>To publish:</p><ol><li>Click <strong>Publish…</strong> next to the version.</li><li>The panel recalls the tag, the repository it comes from and the one it goes to. Publishing is public and irreversible.</li><li>Type the tag in the <strong>Type … to confirm</strong> field: the <strong>Publish</strong> button only enables then.</li></ol><p>The engine refuses, and says so, if the release does not exist on the internal channel, if it is already public, or in semi-auto mode.</p>',9)),s(o,{name:"release-public",alt:"The Public channel: internally delivered versions, ready to publish"}),e[4]||(e[4]=n('<h3 id="configure-the-delivery" tabindex="-1">Configure the delivery <a class="header-anchor" href="#configure-the-delivery" aria-label="Permalink to &quot;Configure the delivery&quot;">​</a></h3><ol><li>Click a module in <strong>Configured stacks</strong> to prefill the form, or enter its name in <strong>Stack</strong>.</li><li>Enter the <strong>Build command</strong>, for instance <code>pnpm build</code>. For a module, it runs in its directory.</li><li>List the <strong>Artifacts</strong>, for instance <code>dist/*.zip</code>. Leaving this field empty keeps those already saved.</li><li>Click <strong>Save the delivery</strong>.</li></ol><p>Further down, <strong>Delivery channels</strong> sets the target&#39;s two release repositories: <strong>Internal release repository</strong> (<code>owner/name</code>; empty = the origin repository) and <strong>Public release repository</strong> (<code>owner/name</code>; empty = no public delivery). Click <strong>Save the channels</strong>.</p><h3 id="read-the-history" tabindex="-1">Read the history <a class="header-anchor" href="#read-the-history" aria-label="Permalink to &quot;Read the history&quot;">​</a></h3><p><strong>Delivery history</strong>, at the bottom of the screen, lists every delivery run, with its columns <strong>Date</strong>, <strong>Channel</strong> (internal or public), <strong>Target</strong>, <strong>Tag</strong> (linking to the release when it exists), <strong>Repository</strong> and <strong>Outcome</strong> (<strong>delivered</strong> or <strong>stopped</strong>). It lives in <code>.effortless/deliveries.json</code>, versioned with the project.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>An agent does the same through <code>effortless_release_plan</code> (the plan) and <code>effortless_release_apply</code> (the run, after your consent). Both take <code>stack</code> to target a module. It configures delivery through <code>effortless_release_delivery_set</code> and the channels through <code>effortless_release_channels_set</code>. It publishes through <code>effortless_release_promote</code>, which requires repeating the tag in <code>confirm</code> — after your explicit consent. It reads the history through <code>effortless_deliveries</code>.</p>',7))])}const v=a(h,[["render",c]]);export{b as __pageData,v as default};
